 slug=s['slug'];d=ROOT/'read'/slug;d.mkdir(parents=True,exist_ok=True)
 prev=next((x for x in sections if x['slug']==s['prev']),None)
 nxt=next((x for x in sections if x['slug']==s['next']),None)
