def release_card(pub):
 editions=[]
 for edition in pub['editions']:
  editions.append(f'''<article class="library-edition"><img src="../{html.escape(edition['cover'])}" alt="{html.escape(pub['title'])} {html.escape(edition['name'])} cover" loading="lazy" width="994" height="1536"><div><span class="eyebrow">{html.escape(edition['name'])}</span><h3>{html.escape(edition['label'])}</h3><p>{html.escape(edition['description'])}</p><div class="library-edition-actions"><a class="btn btn-primary" href="../{html.escape(edition['epub'])}" download>EPUB <span aria-hidden="true">↓</span></a><a class="btn btn-outline" href="../{html.escape(edition['pdf'])}" download>PDF reader proof <span aria-hidden="true">↓</span></a></div></div></article>''')
 return f'''<section class="library-release" aria-labelledby="featured-book"><div class="library-release-intro"><div><span class="eyebrow">Available · Foundational book</span><h2 id="featured-book">{html.escape(pub['title'])}</h2><p class="library-subtitle">{html.escape(pub['subtitle'])}</p></div><p>{html.escape(pub['summary'])}</p></div><div class="library-editions">{''.join(editions)}</div><div class="library-release-foot"><p><strong>Two covers, one text.</strong> Both versions have exactly the same readings, diagrams and illustrations.</p><a class="text-link" href="../read/">Or read the complete book online {SVG_ARROW}</a></div></section>'''

planned=''.join(f'''<article class="library-planned-card"><span class="library-type">{html.escape(t['category'])}</span><h3>{html.escape(t['title'])}</h3><p>{html.escape(t['summary'])}</p><span class="library-status">In development · Not yet available</span></article>''' for t in catalogue['planned'])
downloads=f'''<section class="shell page-hero library-hero"><span class="eyebrow">The library</span><h1>Ideas worth returning to.</h1><p class="lead">Books, reflections and future learning resources exploring chance, choice and the ways our lives shape one another.</p><p>Everything currently available is free to read or download, without an account. The collection can grow without turning the site into a storefront.</p></section><div class="shell library-layout"><div class="library-count"><span>01</span><div><strong>Available now</strong><small>One complete work · Two cover choices</small></div></div>{''.join(release_card(pub) for pub in catalogue['available'])}<section class="library-upcoming"><div class="section-head split"><div><span class="eyebrow">The collection ahead</span><h2>More than one book.</h2></div><p>The library is being designed to accommodate shorter essays, guided reflections and additional literature as they are written and prepared for publication. These are plans, not available downloads.</p></div><div class="library-planned-grid">{planned}</div></section><section class="library-guide"><div><h2>Choose how to read.</h2><p><strong>EPUB</strong> is best for adjustable text and dedicated ebook readers. <strong>PDF</strong> preserves the fixed illustrated page layout. The PDFs currently supplied are reader proofs, pending final digital accessibility and production checks.</p></div><div><h2>Open by principle.</h2><p>Foundational writings remain accessible without membership, payment or registration. Additional resources may have their own formats and availability when they are ready.</p></div></section></div>'''
(ROOT/'downloads'/'index.html').write_text(document('Library',downloads,base='../',active='downloads',desc='Explore The Book of Chance and a growing library of philosophical readings and resources, free to access.'),encoding='utf8')

# FELLOWSHIP COMMUNITY — enticing without misrepresenting membership or services as operational.
community=f'''<section class="shell community-hero community-hero-v6"><div class="community-hero-copy"><span class="eyebrow"><span class="eyebrow-line"></span>The Fellowship of Chance · A community in development</span><h1>Belong somewhere.<br><em>Make possibilities together.</em></h1><p class="lead">A conversation can change how we see our lives. A person we meet can open a door we did not know existed. What might happen if we made more room for both?</p><p>We want to build a thoughtful community where people of different generations and experiences come together to share knowledge, encourage growth, and work on things that matter.</p><div class="button-line"><a class="btn btn-primary" href="#why-participate">Discover what could happen {SVG_ARROW}</a><a class="btn btn-outline" href="#community-interest">Hear when we open</a></div><p class="community-hero-note">The Fellowship is not yet open for registered membership. Its foundational book remains free for everyone.</p></div><div class="community-hero-emblem"><img src="../assets/brand-mark.svg?v=5" width="440" height="440" alt="" decoding="async"><p>Through chance, we meet. Through choice, we grow. Together, we create possibility.</p></div></section>
<div class="shell"><div class="thin-rule"></div></div>
<section class="shell section-space community-why" id="why-participate"><div class="section-head split"><div><span class="eyebrow">Why belong?</span><h2>Not another list of contacts.<br><em>Real relationships.</em></h2></div><p>The Fellowship is not a place to advertise yourself or collect credentials. The idea is simpler: get to know one another through conversation and shared activity, and discover what those relationships can make possible.</p></div><div class="community-pillars"><article><span class="pillar-num">01</span><h3>Find a different perspective.</h3><p>Explore questions about uncertainty, hope and change with people whose experiences differ from yours. You can disagree, learn, and still belong.</p></article><article><span class="pillar-num">02</span><h3>Learn from someone else.</h3><p>Imagine an older member sharing a lifetime of lessons, and a younger member sharing a skill they have just learned. Mentorship should be a two-way exchange.</p></article><article><span class="pillar-num">03</span><h3>Do something together.</h3><p>Turn shared interests into useful work: a learning session, a local project, an introduction or an act that widens someone else’s opportunities.</p></article></div></section>
<section class="shell community-possibilities"><div class="section-head split"><div><span class="eyebrow">A picture of participation</span><h2>Small beginnings.<br>Meaningful connections.</h2></div><p>These are illustrations of what the Fellowship hopes to enable, not testimonials or activities that have already taken place.</p></div><div class="community-scenarios"><article><span class="scenario-num">01 / A conversation</span><h3>Someone listens.</h3><p>At a gathering, someone shares that they are uncertain about their next step. Another person offers a perspective they had not considered. Nothing is promised. A possibility appears.</p></article><article><span class="scenario-num">02 / A shared skill</span><h3>Someone teaches.</h3><p>A member offers to show others how to use a tool, repair something or develop a skill. People leave with knowledge they did not have before.</p></article><article><span class="scenario-num">03 / A joint effort</span><h3>People act.</h3><p>A small group identifies a local need and works together on an achievable project. The work is practical, its limitations are clear, and its impact can be reported.</p></article></div></section>
<section class="community-manifesto"><div class="shell community-manifesto-inner"><span class="eyebrow">Five values · One shared direction</span><h2>Hope. Acceptance.<br>Reflection. Growth. Community.</h2><p>These values guide how we approach difficulty, welcome disagreement, and support people without claiming to control their choices.</p><a class="text-link" href="../read/reflection-and-growth/">Explore the values in the book {SVG_ARROW}</a></div></section>
<section class="shell section-space community-work"><div class="section-head"><span class="eyebrow">Our first-year development priorities</span><h2>From ideals to useful support.</h2><p>We intend to build these programmes carefully. They are <strong>not yet operating</strong>, and no service, introduction or financial assistance is guaranteed.</p></div><div class="community-work-grid"><article><span class="work-icon">↗</span><h3>Mentorship &amp; guidance</h3><p>Supportive conversations and, later, a supervised adult-to-adult mentorship programme with clear consent and expectations.</p></article><article><span class="work-icon">⌁</span><h3>Collaborative projects</h3><p>Member-led activities, local initiatives and opportunities to teach and learn together, supported by accountable coordination.</p></article><article><span class="work-icon">◌</span><h3>Practical support</h3><p>Appropriate, confidential assistance during hardship. Any material or financial aid would require additional eligibility and safeguarding arrangements before launch.</p></article></div></section>
<section class="community-support" id="support-the-vision"><div class="shell"><div class="support-intro"><span class="eyebrow">Building a Fellowship that can last</span><h2>What your support could make possible.</h2><p class="lead">Because a welcoming, useful community takes more than good intentions. Accessible resources, safe places to meet, coordination and real-world projects all need time, care and sometimes money.</p><p>When our governance and financial safeguards are ready, people who believe in this work will be able to help build its foundations. Financial contributions will be <strong>voluntary</strong>; ordinary Membership will remain free.</p></div><div class="support-areas"><article><span class="support-count">01</span><h3>Keep learning accessible</h3><p>Maintain free foundational literature, accessible digital resources and practical material for readers and future Members.</p></article><article><span class="support-count">02</span><h3>Make gatherings possible</h3><p>Support the tools, coordination and safeguarding needed for meaningful online and local meetings.</p></article><article><span class="support-count">03</span><h3>Help projects take shape</h3><p>Fund approved, clearly budgeted community projects after appropriate oversight and spending rules exist.</p></article><article><span class="support-count">04</span><h3>Build responsible support systems</h3><p>Develop training, safe mentoring and fair assistance procedures before offering sensitive services. Any hardship fund would have separate controls.</p></article></div><div class="support-first-goal"><div><span class="eyebrow">An example of an achievable first goal</span><h3>One well-run pilot gathering.</h3></div><p>Before requesting funds, we could publish a small, itemised budget for an accessible, adult-only discussion event with appropriate moderation, then report what took place and what was learned. This is a possible future project, <strong>not an active fundraising campaign</strong>.</p></div><div class="support-accountability"><div><span class="eyebrow">What supporters should expect</span><h3>Transparency before fundraising.</h3><p>Our intended standard is to publish what funds are being requested for, how they are spent and what outcomes are achieved—while protecting donor identities and the privacy of people receiving help.</p></div><div class="support-promises"><p><span aria-hidden="true">✓</span> Public budgets and meaningful financial reporting</p><p><span aria-hidden="true">✓</span> Independent oversight and clear spending authority</p><p><span aria-hidden="true">✓</span> No purchasing influence, higher human worth or priority assistance</p><p><span aria-hidden="true">✓</span> No expectation to give beyond one's means</p></div></div><div class="support-notice"><strong>We are not accepting donations yet.</strong> The Fellowship first needs an appropriate legal structure, governance, finance controls and an approved plan for the use of funds. No donation or tax-deductibility claim is made on this page. For now, the best way to help is to read, share thoughtful feedback and follow the development of the community. <a href="#community-interest">Get opening updates {SVG_ARROW}</a></div></div></section>
<section class="shell section-space community-belonging" id="how-belonging-works"><div class="section-head split"><div><span class="eyebrow">How belonging is envisioned</span><h2>Everyone starts with dignity.<br>No one has to pay to belong.</h2></div><p>The complete foundational writings are public. When registered Membership opens, it is intended to be free for adults aged 18 and over. Contribution can mean time, skills, introductions, care or money—within someone's circumstances.</p></div><div class="belonging-table"><div><span>01</span><div><h3>Follower</h3><p>Read the complete foundational writings and explore the philosophy without registration, cost or pressure to agree.</p></div><small>Available now · Read freely</small></div><div><span>02</span><div><h3>Member</h3><p>Planned free adult Membership with protected spaces, gatherings and resources once safely operational. Real names will be used privately in Member spaces, not published openly.</p></div><small>Planned · Not open</small></div><div><span>03</span><div><h3>Senior Member</h3><p>Future recognition for sustained service and affordable regular giving, including confidential exceptions when someone cannot afford to give. Seniority cannot be purchased.</p></div><small>Future pathway</small></div></div></section>
<section class="shell community-questions"><div class="section-head"><span class="eyebrow">Questions worth answering</span><h2>Belonging should be straightforward.</h2></div><div class="community-faq"><details><summary>Will I have to donate to join?</summary><p>No. Ordinary registered Membership is intended to be free. Financial support is separate and voluntary. Becoming a Senior Member is a later recognition process based on sustained service and giving within one's means, with hardship accommodations.</p></details><details><summary>Will donations guarantee opportunities or special treatment?</summary><p>No. Giving would not purchase influence, priority help or access to another person's decisions. The Fellowship cannot guarantee good fortune, connections or outcomes.</p></details><details><summary>Can I contribute without money?</summary><p>Absolutely. Sharing knowledge, helping with a project, listening, making introductions and volunteering are all meaningful contributions. No one should sacrifice their basic wellbeing to demonstrate commitment.</p></details><details><summary>Is the Fellowship already running events or providing assistance?</summary><p>Not yet. Registered Membership, official gatherings, mentoring and hardship services are development goals. The interest list is only for updates about the future opening.</p></details></div></section>
<section class="shell community-status"><div class="status-art"><img src="../assets/artwork/03_part_iii.webp" alt="Network of interconnected paths representing possible relationships" loading="lazy"></div><div><span class="eyebrow">Where things stand</span><h2>The foundation comes first.</h2><p>Before welcoming registered Members or accepting donations, we intend to establish accountable leadership, privacy and safeguarding practices, fair procedures and financial transparency.</p><p>You can already read and share <i>The Book of Chance</i> freely. If you would like to hear when the community is ready to begin, use the separate interest list below.</p><div class="button-line"><a class="btn btn-primary" href="#community-interest">Receive opening updates {SVG_ARROW}</a><a class="btn btn-outline" href="../read/">Read the book</a></div><p class="community-fineprint">The interest list is not Membership; no donations or payment details are collected here.</p></div></section>'''
community += '<section class="shell interest-section" id="community-interest"><div class="interest-intro"><span class="eyebrow">An invitation, not membership</span><h2>Hear when the Fellowship begins.</h2><p>Leave an email address if you would like news about the Fellowship\'s future opening. This is an interest list only: no community account or membership is created, and mentorship or hardship services are not yet available.</p><p class="interest-note">Adults aged 18+ only for this initial interest list. You may use a pseudonym. The full book remains free without signing up.</p></div>\n<div class="interest-panel"><div class="interest-status" data-form-availability role="status" aria-live="polite">The Fellowship interest list is being prepared; it isn\'t accepting submissions yet.</div>\n<form class="interest-form" data-interest-form="fellowship" novalidate>\n<input type="hidden" name="list" value="fellowship-opening"/>\n<div class="form-field"><label for="fellowship-email">Email address <span aria-hidden="true">*</span></label><input id="fellowship-email" type="email" autocomplete="email" inputmode="email" name="email" placeholder="you@example.com" maxlength="254" required></div>\n<div class="form-field"><label for="fellowship-name">Name or pseudonym <small>Optional</small></label><input id="fellowship-name" type="text" name="display_name" autocomplete="nickname" maxlength="80" placeholder="How you\'d like to be addressed"></div>\n<div class="form-honeypot" aria-hidden="true"><label>Leave this field blank<input type="text" tabindex="-1" autocomplete="off" name="_gotcha"></label></div>\n<label class="form-consent"><input type="checkbox" name="adult_confirmation" value="yes" required><span>I confirm I am at least 18 years old.</span></label>\n<label class="form-consent"><input type="checkbox" name="consent" value="yes" required><span>I agree to be contacted by email about the Fellowship\'s opening and understand my submission will be handled by an external form service, potentially outside New Zealand, as described in the <a href="../privacy/">privacy notice</a>. I can withdraw my interest at any time.</span></label>\n<button type="submit" class="btn btn-primary interest-submit" disabled>Register my interest</button>\n<p class="interest-response" data-form-response role="status" aria-live="polite"></p>\n</form><p class="form-fineprint">No subscription to book marketing, no fee, no official membership.</p></div></section>'
community=community.replace('No email addresses, applications, donations or membership payments are collected on this prototype.','No membership applications, donations or payments are accepted. An optional interest list will open only after the registration service is configured.')
(ROOT/'community'/'index.html').write_text(document('The Fellowship',community,base='../',active='community',desc='Explore The Fellowship of Chance: a developing free-to-join community for reflection, mentorship, shared projects and practical support. See how you could participate and help build its future.'),encoding='utf8')

# PHYSICAL BOOK — nontransactional interest preview
print_page=f'''<section class="shell page-hero"><span class="eyebrow">A future physical edition</span><h1>Some books are meant to be held.</h1><p class="lead">We're exploring a first paperback printing of <i>The Book of Chance</i>. Choose a cover, and follow the journey from digital pages to a physical book.</p></section><section class="shell print-preview"><div class="print-books"><div class="print-art-stack"><img id="selected-print-cover" src="../assets/covers/light-cover.webp" alt="Light Edition book cover" width="994" height="1536"><span class="book-bottom-shadow" aria-hidden="true"></span></div></div><div class="print-info"><span class="eyebrow">Two covers · identical interiors</span><h2>Your first choice.</h2><p>Every copy contains the same twelve readings, parables and interior artwork. The design you choose is simply the first choice of your reading journey.</p><div class="cover-chooser" role="group" aria-label="Choose your preferred paperback cover"><button type="button" class="cover-choice selected" data-cover-choice="light" aria-pressed="true"><span class="choice-swatch light-swatch"></span><span><strong>Light</strong><small>White & charcoal</small></span></button><button type="button" class="cover-choice" data-cover-choice="dark" aria-pressed="false"><span class="choice-swatch dark-swatch"></span><span><strong>Dark</strong><small>Charcoal & ivory</small></span></button></div><button type="button" class="btn btn-primary" id="save-cover-choice">Save my cover preference</button><p class="micro-status" id="cover-save-status" role="status" aria-live="polite">Saved only on this device. No order or reservation is placed.</p></div></section><section class="shell"><div class="print-state"><div><span class="eyebrow">Printing status</span><h2>Preparing the first printing.</h2><p>Our optional interest list is shown below. We will announce a clear print threshold, price, shipping arrangements and closing date before accepting paid pre-orders. No payment details are collected here.</p></div><div class="state-pill"><span class="state-dot"></span>Planning stage</div></div></section><section class="shell section-space"><div class="section-head"><span class="eyebrow">How it could work</span><h2>From interest to first printing.</h2></div><div class="steps"><div><span>01</span><h3>Register interest</h3><p>When the list opens, readers choose Light or Dark and provide contact details voluntarily.</p></div><div><span>02</span><h3>Set a transparent goal</h3><p>We'll publish a viable print target, pricing, estimated dispatch window and refund terms before collecting payment.</p></div><div><span>03</span><h3>Print & deliver</h3><p>If the paid pre-order goal is met, we print and ship. If not, the campaign would issue the stated full refunds.</p></div></div></section>'''
print_page += '<section class="shell interest-section" id="physical-interest"><div class="interest-intro"><span class="eyebrow">First printing · Interest list</span><h2>Be notified when print plans are ready.</h2><p>Let us know which physical cover interests you. This helps estimate demand, but it is not an order or a guarantee of availability. We will announce prices, shipping options, a campaign threshold and a closing date before any paid pre-orders.</p><p class="interest-note">We will only contact you about the physical edition. This list is separate from Fellowship updates.</p></div>\n<div class="interest-panel"><div class="interest-status" data-form-availability role="status" aria-live="polite">The physical-edition interest list is being prepared; it isn\'t accepting submissions yet.</div>\n<form class="interest-form" data-interest-form="print" novalidate>\n<input type="hidden" name="list" value="physical-first-printing"/>\n<div class="form-field"><label for="print-email">Email address <span aria-hidden="true">*</span></label><input id="print-email" name="email" type="email" inputmode="email" autocomplete="email" maxlength="254" placeholder="you@example.com" required></div>\n<div class="form-field"><label for="print-edition">Preferred cover</label><select id="print-edition" name="edition" required><option value="light">Light Edition</option><option value="dark">Dark Edition</option></select></div>\n<div class="form-grid-small"><div class="form-field"><label for="print-copies">Copies of interest</label><select id="print-copies" name="copies" required><option value="1">1</option><option value="2">2</option><option value="3">3</option><option value="4">4</option><option value="5">5</option><option value="6-10">6–10</option></select></div><div class="form-field"><label for="print-country">Country or region <small>Optional</small></label><input id="print-country" name="country" type="text" autocomplete="country-name" maxlength="80" placeholder="For delivery estimates"></div></div>\n<div class="form-honeypot" aria-hidden="true"><label>Leave this field blank<input name="_gotcha" type="text" tabindex="-1" autocomplete="off"></label></div>\n<label class="form-consent"><input type="checkbox" name="consent" value="yes" required><span>I agree to receive email updates about the planned physical printing and understand my submission will be handled by an external form service, potentially outside New Zealand, as described in the <a href="../privacy/">privacy notice</a>. I can withdraw my interest at any time.</span></label>\n<button type="submit" class="btn btn-primary interest-submit" disabled>Register print interest</button>\n<p class="interest-response" data-form-response role="status" aria-live="polite"></p>\n</form><p class="form-fineprint">No payment, shipping address or official reservation is collected.</p></div></section>'
(ROOT/'print'/'index.html').write_text(document('Physical editions',print_page,base='../',active='print',desc='Explore the planned Light and Dark paperback editions of The Book of Chance. Printing is not yet open and no orders are being collected.'),encoding='utf8')

# ABOUT
about=f'''<section class="shell page-hero about-hero"><span class="eyebrow">About the philosophy</span><h1>What can we shape<br>within uncertainty?</h1><p class="lead">Confluent Humanism explores the meeting of circumstance, chance, agency and ethical responsibility. It draws on questions people have asked across many philosophical traditions.</p></section><section class="shell about-grid"><div class="about-long"><h2>An invitation to think.</h2><p><i>The Book of Chance</i> is a work of reflective philosophy, not a revelation or a claim to have settled scientific debates. Its central conviction—that chance is fundamental and the future is not entirely predetermined—is presented as a philosophical position open to criticism.</p><p>Its ethical commitments begin with dignity, meaningful action, attention to unequal circumstances and responsibility toward one another and the living world. Those commitments deserve their own arguments; they cannot be derived simply from randomness.</p><p>The work draws upon prior conversations in philosophy about causation, luck, free will, care, moral responsibility and practical opportunity. Its contribution is in bringing ideas together into a distinct synthesis and a way of living with uncertainty—not claiming they were all invented here.</p><h2>The author</h2><p>H is the pseudonymous authorial voice of <i>The Book of Chance</i>. The name signals authorship, not special authority over readers or immunity from disagreement.</p><h2>About the Fellowship</h2><p>The book is associated with the envisioned Fellowship of Chance, a proposed community centred on reflection, growth and support for others. The book stands on its own: reading it involves no membership, loyalty, donation or other obligation.</p><p>The Fellowship is not represented here as an active membership service. Readers may explore the philosophy independently.</p></div><aside class="about-side"><div class="about-figure"><img src="../assets/artwork/03_part_iii.webp" loading="lazy" alt="A network of charcoal and blue connections symbolising interdependent lives"><p>Our lives are shaped by one another, even where their paths are unknown to us.</p></div><div class="aside-quote"><span class="eyebrow">The five values</span><p>Hope<br>Acceptance<br>Reflection<br>Growth<br>Community</p><a class="text-link" href="../read/reflection-and-growth/">Explore the readings {SVG_ARROW}</a></div></aside></section>'''
(ROOT/'about'/'index.html').write_text(document('About',about,base='../',active='about',desc='About Confluent Humanism, H and The Book of Chance: a philosophical synthesis exploring chance, agency and shared ethical responsibility.'),encoding='utf8')

(ROOT/'privacy').mkdir(parents=True,exist_ok=True)
(ROOT/'privacy'/'index.html').write_text(document('Privacy','<section class="shell page-hero privacy-hero"><span class="eyebrow">Transparency &amp; privacy</span><h1>Interest list privacy.</h1><p class="lead">A short explanation of what the optional interest forms collect, how the information is used, and how to withdraw it.</p><p>This notice is about the future Fellowship and physical-book interest lists. You do not need to provide personal details to read or download <i>The Book of Chance</i>.</p></section>\n<section class="shell privacy-layout"><div class="privacy-prose">\n<h2>Who is responsible?</h2><p>The Book of Chance project, represented publicly by H, is responsible for the two interest lists. For privacy questions or requests, contact <a href="#" data-privacy-email hidden></a><span data-privacy-contact-missing>the project through the contact channel that will be published before registrations open.</span></p>\n<h2>What we collect</h2><p><strong>Fellowship interest:</strong> your email address, optional display name, confirmation that you are at least 18, and your consent to be contacted about the proposed community. A display name may be a pseudonym at this stage; this is not official membership.</p><p><strong>Physical-book interest:</strong> your email address, preferred cover (Light or Dark), intended quantity, optional country or region, and your consent to receive print-campaign updates. This is not a purchase, deposit, reservation or binding commitment.</p>\n<h2>Why we collect it</h2><p>Only to send updates relating to the list you chose. Signing up to one list does not add you to the other, and neither list is used to register you as a Fellowship Member. We do not sell contact lists or use them for unrelated marketing.</p>\n<h2>Where information goes</h2><p>If the forms are activated, submissions are sent to Formspree, an external form service, and may be processed or stored outside New Zealand. You should review <a href="https://formspree.io/legal/privacy-policy/" target="_blank" rel="noopener noreferrer">Formspree’s privacy policy</a> before opting in. Authorised project administrators can view and manage submissions. The public GitHub Pages website itself does not store form entries in its repository.</p>\n<h2>Retention, access and correction</h2><p>We will retain interest records only while they are needed to administer the chosen list, review them at least annually, and delete them when no longer needed. You can request access, correction, removal or an end to messages by contacting the project address shown above. You can withdraw from one list without affecting the other. Removal requests will be actioned through the form service and any associated records under our control.</p>\n<h2>Security and limits</h2><p>We intend to restrict access to authorised administrators and use the form provider\'s access controls. No online service can promise absolute security. Please do not include personal stories, medical details, addresses, or other sensitive information in these forms.</p>\n<h2>What is not collected</h2><p>No payment details, delivery address, legal identity documents or membership declarations are requested on this site. Reading preferences may be stored locally on your own device, as described in the reader; they are not sent to H by these forms.</p>\n<p class="privacy-date">Notice dated 22 November 2026. This page should be updated whenever collection, providers or retention practices change. You may request access to or correction of your information using the contact address above.</p>\n</div><aside class="privacy-side"><span class="eyebrow">No account required</span><p>Read the book in full without signing up for either list.</p><a class="btn btn-outline" href="../read/">Read for free</a><div class="thin-rule"></div><a href="../community/">Fellowship interest</a><a href="../print/">Physical edition interest</a></aside></section>',base='../',active='privacy',desc='Privacy notice for The Book of Chance interest lists.'),encoding='utf8')

